-- V2: users.
-- One row per person who has a Spendly account.
-- Ids are UUIDv7, generated by Hibernate in Java (see BaseEntity), so no DB default.
-- created_at / updated_at are set by Hibernate in UTC.

CREATE TABLE users (
    id              UUID        PRIMARY KEY,
    email           TEXT        NOT NULL,
    -- NULL only for future Google-only users, who have no password.
    -- Registration in phase 1 always stores a BCrypt hash.
    password_hash   TEXT,
    name            TEXT        NOT NULL,
    email_verified  BOOLEAN     NOT NULL DEFAULT false,
    -- NULL until the user picks a currency during onboarding.
    currency        TEXT,
    timezone        TEXT        NOT NULL DEFAULT 'UTC',
    week_start      TEXT        NOT NULL DEFAULT 'MONDAY',
    theme           TEXT        NOT NULL DEFAULT 'SYSTEM',
    created_at      TIMESTAMPTZ NOT NULL,
    updated_at      TIMESTAMPTZ NOT NULL,

    -- The unique index behind this constraint also serves "find user by email".
    CONSTRAINT users_email_key        UNIQUE (email),
    -- Emails are stored lowercase, so the UNIQUE above is effectively case-insensitive
    -- even if some future code forgets to lowercase.
    CONSTRAINT users_email_lowercase  CHECK (email = lower(email)),
    CONSTRAINT users_email_length     CHECK (length(email) <= 254),
    -- When a hash exists it must look like BCrypt ($2a$12$ + 53 chars = 60 chars).
    -- Stops a bug from ever storing a plain-text password. NULL passes a CHECK.
    CONSTRAINT users_password_bcrypt  CHECK (password_hash ~ '^\$2[aby]\$\d{2}\$.{53}$'),
    CONSTRAINT users_name_length      CHECK (length(name) BETWEEN 1 AND 100),
    CONSTRAINT users_currency_format  CHECK (currency ~ '^[A-Z]{3}$'),
    CONSTRAINT users_week_start_valid CHECK (week_start IN ('MONDAY', 'SATURDAY', 'SUNDAY')),
    CONSTRAINT users_theme_valid      CHECK (theme IN ('SYSTEM', 'LIGHT', 'DARK'))
);
